import java.io.BufferedReader
import java.io.InputStreamReader

class ConsoleScanner {
    private var _line: Array<String> = emptyArray()
    private var _iterator = 0
    private val reader = BufferedReader(InputStreamReader(System.`in`))

    fun nextInt(): Int {
        if (_iterator >= _line.size) {
            _line = reader.readLine()?.split(" ")?.toTypedArray() ?: emptyArray()
            _iterator = 0
        }
        if (_line.isEmpty()) throw IndexOutOfBoundsException("Input string is empty")
        return _line[_iterator++].toInt()
    }

    fun nextLong(): Long {
        if (_iterator >= _line.size) {
            _line = reader.readLine()?.split(" ")?.toTypedArray() ?: emptyArray()
            _iterator = 0
        }
        if (_line.isEmpty()) throw IndexOutOfBoundsException("Input string is empty")
        return _line[_iterator++].toLong()
    }

    fun read(): Int = System.`in`.read()

    fun readLine(): String? = reader.readLine()
}

fun main() {
    val sc = ConsoleScanner()
    var n = sc.nextLong()
    val a = sc.nextLong()
    val b = sc.nextLong()
    val c = sc.nextLong()
    var liters = 0L
    if (b - c < a && n >= b) {
        val i = (n - b) / (b - c) + 1
        liters += i
        n -= i * (b - c)
    }
    liters += n / a
    println(liters)
}

